import { useEffect, useState } from "react";
import { useThrottledCallback } from "use-debounce";
export function useSignalValueThrottled(signalValue) {
    const [value, setValue] = useState(signalValue.value);
    const refresh = useThrottledCallback((value) => setValue(value), 400);
    useEffect(() => signalValue.onChange.addForHook(refresh), [signalValue, refresh]);
    return value;
}
