async function loadDynamicData(hold, log) {
    log("Generating dynamic info", -1, "Speech locations");
    regenerateHoldSpeechLocations(hold);
    await tryToYieldToUi();
    log("Generating dynamic info", -1, "Data uses");
    regenerateHoldDataUses(hold);
    await tryToYieldToUi();
    for (const [variableId, variable, index] of hold.variables) {
        log("Generating dynamic info", index / hold.variables.size, `Hold variable ${variable.name.newValue}`);
        regenerateHoldVariableUses(hold, variableId);
        await tryToYieldToUi();
    }
    for (const [characterId, character, index] of hold.characters) {
        log("Generating dynamic info", index / hold.characters.size, `Hold character ${character.name.newValue}`);
        regenerateHoldCharacterUses(hold, characterId);
        await tryToYieldToUi();
    }
}
function str(node, attribute) {
    const value = node.getAttribute(attribute);
    assertNotNull(value, `Missing attribute ${attribute} in node ${node.tagName}`, node);
    return value;
}
function int(node, attribute) {
    const value = node.getAttribute(attribute);
    assertNotNull(value, `Missing attribute ${attribute} in node ${node.tagName}`, node);
    return parseInt(value, 10);
}
function bool(node, attribute) {
    const value = node.getAttribute(attribute);
    assertNotNull(value, `Missing attribute ${attribute} in node ${node.tagName}`, node);
    return parseInt(value, 10) === 1;
}
function strU(node, attribute) {
    return node.hasAttribute(attribute) ? str(node, attribute) : undefined;
}
function intU(node, attribute) {
    return node.hasAttribute(attribute) ? int(node, attribute) : undefined;
}
function boolU(node, attribute) {
    return node.hasAttribute(attribute) ? int(node, attribute) === 1 : undefined;
}
function intArray(node, attribute) {
    return str(node, attribute)
        .trim()
        .split(" ")
        .filter(Boolean)
        .map(x => parseInt(x, 10));
}
function intArrayU(node, attribute) {
    return node.hasAttribute(attribute) ? intArray(node, attribute) : undefined;
}
function* querySelectorAll(document, query) {
    const elements = document.querySelectorAll(query);
    const total = elements.length;
    for (let index = 0; index < total; index++) {
        yield [elements[index], index, total];
    }
}
export class XmlToHoldError extends Error {
    constructor(hold, message, options) {
        super(message, options);
        this.hold = hold;
    }
    get rootError() {
        let cause = this.cause;
        let loopDepth = 0;
        let lastError;
        while (cause) {
            if (loopDepth++ > 1000) {
                break;
            }
            else if (cause instanceof Error) {
                lastError = cause;
                cause = lastError.cause;
            }
            else if (typeof cause === "object" && "cause" in cause) {
                cause = cause.cause;
            }
            else {
                break;
            }
        }
        return lastError;
    }
    get diffXmlErrorCause() {
        let cause = this.cause;
        let loopDepth = 0;
        while (cause) {
            if (loopDepth++ > 1000) {
                break;
            }
            else if (cause instanceof DiffXmlError) {
                return cause;
            }
            else if (typeof cause === "object" && "cause" in cause) {
                cause = cause.cause;
            }
            else {
                break;
            }
        }
        return undefined;
    }
}
