        this.players = new OrderedMap();
        this.variables = new OrderedMap();
        this.speeches = new OrderedMap();
        this.entrances = new OrderedMap();
        this.datas = new OrderedMap();
        this.characters = new OrderedMap();
        this.levels = new OrderedMap();
