import { useCallback, useState } from "react";
export default function useSortableTableSort(defaultSort) {
    const [sortBy, setSortBy] = useState(defaultSort);
    const [sortAsc, setSortAsc] = useState(true);
    const onSort = useCallback((newSortBy) => {
        if (newSortBy === sortBy) {
            setSortAsc(!sortAsc);
        }
        else {
            setSortBy(newSortBy);
            setSortAsc(true);
        }
    }, [sortAsc, sortBy]);
    return { sortBy, sortAsc, onSort };
}
